create table if not exists authorization_decisions(decision_id uuid primary key,idempotency_key varchar(128) not null unique,payment_id varchar(128) not null,issuer_id varchar(128) not null,amount_minor bigint not null,currency char(3) not null,status varchar(32) not null,reason varchar(64) not null,created_at timestamptz not null default now()); create table if not exists outbox_events(event_id uuid primary key,event_type varchar(128) not null,aggregate_id varchar(128) not null,payload text not null,created_at timestamptz not null default now(),published_at timestamptz);